#!/usr/bin/env python3
# gen_ssot_v4_rs.py -- t9 alpha2 (FABER) generator.
#
# Regenerates the SSOT v4 Rust artifacts from the FROZEN SSOT
# (01_SSOT of integrado-supremo; byte-identical copies live in this release
# under SSOT/). Emits:
#  1. detector_policy.rs -> full regenerated file (original + additive v4
#     section + v4 unit tests; QUOTEBASE legacy tables retained: coexistence,
#     nothing deleted). Materializes DFAC['D_']:=0.80 (workbook LEEME + F04
#     generator fix).
#  2. strategy_hop_map.v4.fixture.json -> same schema as the legacy
#     strategy_hop_map.fixture.json; (m,h) from 01_SSOT/strategy_hop_map.json;
#     s (surface) from workbook sheet CLASIFICACION_264.
#  3. hop_cycle_bridge.verify.txt -> asserts MIN_BRIDGE_HOPS==3 and
#     MAX_BRIDGE_HOPS==7 in live source (stub v4 "ciclos 3-7 hops" satisfied
#     by existing code; verification, not patch).
# Never edits anything by hand: rows are emitted only from SSOT bytes.
import csv, json, re
from pathlib import Path

WS = Path(__file__).resolve().parents[5]
R = Path(__file__).resolve().parent.parent
SUP = WS / ".tmp-inbox" / "integrado-supremo"
DET_CSV = R / "SSOT" / "detector_policy.csv"
HOP_JSON = R / "SSOT" / "strategy_hop_map.json"
XLSX = SUP / "ArbitrageX_v4_264_60hojas.xlsx"
OUT = R / "gen"

def emit_detector_section():
    with open(DET_CSV, encoding="utf-8-sig") as f:
        rows = list(csv.DictReader(f))
    assert len(rows) == 60, "SSOT detector rows != 60"
    total = sum(int(r["ESTRATEGIAS"]) for r in rows)
    assert total == 264, "SSOT strategies sum != 264"
    body = ",\n".join(
        '    SsotDetectorPolicy {{ detector_id: "{d}", family: "{f}", strategy_count: {n} }}'
        .format(d=r["DETECTOR"], f=r["FAMILIA"], n=int(r["ESTRATEGIAS"])) for r in rows)
    d_rows = [r for r in rows if r["FAMILIA"] == "D_"]
    assert len(d_rows) == 5 and all(int(r["ESTRATEGIAS"]) == 6 for r in d_rows), "D_ drift"
    return (
"\n// ---------------------------------------------------------------------------\n"
"// SSOT v4 (integrado-supremo 01_SSOT) - GENERATED by\n"
"// docs/integration-v4/releases/" + R.name + "/gen/gen_ssot_v4_rs.py (t9, alpha2 FABER).\n"
"// Source of truth: 01_SSOT/detector_policy.csv (60 rows, strategies sum 264)\n"
"// + 01_SSOT/strategy_hop_map.json (264 strategies, |Omega|=1436).\n"
"// Do not edit rows by hand; regenerate. The QUOTEBASE-264 tables above stay\n"
"// authoritative for the running wire (coexistence: nothing is deleted) until\n"
"// the v4 release is promoted (t6/t14). Row order == SSOT csv row order.\n"
"// ---------------------------------------------------------------------------\n"
"\n"
"/// One row of the v4 SSOT `detector_policy.csv` (DETECTOR,FAMILIA,ESTRATEGIAS).\n"
"pub struct SsotDetectorPolicy {\n"
"    pub detector_id: &'static str,\n"
"    pub family: &'static str,\n"
"    pub strategy_count: u16,\n"
"}\n"
"\n"
"/// 60 v4 detectors in SSOT csv row order (R_, CF_, C_, D_, E_, P_, L_, I_,\n"
"/// M_, N_, X_, OBSERVE). OBSERVE01/OBSERVE02 carry strategy_count 0\n"
"/// (telemetry-only family, mirrors HotSeed::TelemetryOnly above).\n"
"pub static SSOT_V4_DETECTOR_POLICIES: [SsotDetectorPolicy; 60] = [\n"
+ body + ",\n"
"];\n"
"\n"
"/// DFAC - Detector-Family Admission Coefficient (SSOT v4).\n"
"///\n"
"/// Materializes the generator fix recorded in the v4 workbook: sheet LEEME\n"
"/// \"FIX: DFAC[D_]=0.80 -> DERIVATIVES con positivos\" and sheet F04 row D_\n"
"/// (\"D_ Derivados (fix DFAC D_=0.80) 5 30\", BASE 1982 -> IMP 3560). Before\n"
"/// the fix the derivatives family emitted zero positives; after it the\n"
"/// workbook INVARIANTES sheet reports DERIV_POS>0 == 1982 (OK).\n"
"pub const DFAC_D_UNDERSCORE: f64 = 0.80;\n"
"\n"
"/// DFAC by family (SSOT v4): 0.80 for `D_` (derivatives fix), 1.0 (neutral)\n"
"/// for every other family and for unknown families - the coefficient never\n"
"/// silently zeroes a family it does not know.\n"
"pub fn dfac(family: &str) -> f64 {\n"
"    if family == \"D_\" {\n"
"        DFAC_D_UNDERSCORE\n"
"    } else {\n"
"        1.0\n"
"    }\n"
"}\n")

V4_TESTS = """
    // --- SSOT v4 (t9 alpha2): 01_SSOT invariants --------------------------------
    #[test]
    fn ssot_v4_detector_table_matches_ssot() {
        assert_eq!(SSOT_V4_DETECTOR_POLICIES.len(), 60);
        let total: u32 = SSOT_V4_DETECTOR_POLICIES
            .iter()
            .map(|p| p.strategy_count as u32)
            .sum();
        assert_eq!(total, 264, "SSOT strategies must sum 264");
        let d: Vec<&SsotDetectorPolicy> = SSOT_V4_DETECTOR_POLICIES
            .iter()
            .filter(|p| p.family == "D_")
            .collect();
        assert_eq!(d.len(), 5, "D_ family has 5 detectors");
        assert!(
            d.iter().all(|p| p.strategy_count == 6),
            "each D_ detector carries 6 strategies"
        );
    }

    #[test]
    fn dfac_fix_is_materialized() {
        assert_eq!(dfac("D_"), 0.80, "FIX: DFAC[D_]=0.80 (workbook LEEME/F04)");
        assert_eq!(dfac("R_"), 1.0);
        assert_eq!(dfac("CF_"), 1.0);
        assert_eq!(dfac("OBSERVE"), 1.0);
        assert_eq!(dfac("unknown_family"), 1.0, "neutral for unknown families");
        assert_eq!(DFAC_D_UNDERSCORE, 0.8);
    }
"""

def rebuild_detector_policy_rs():
    src = (WS / "backend/searcher-rs/src/detector_policy.rs").read_text(encoding="utf-8")
    nl = "\r\n" if "\r\n" in src else "\n"
    s = src.replace("\r\n", "\n")
    marker = "\n#[cfg(test)]\nmod tests {\n"
    assert marker in s, "test module marker not found"
    assert "SSOT_V4_DETECTOR_POLICIES" not in s, "v4 section already present"
    s = s.replace(marker, "\n" + emit_detector_section() + marker, 1)
    s = s.rstrip("\n")
    assert s.endswith("}"), "file must end with the tests module brace"
    s = s[:-1] + V4_TESTS.rstrip("\n") + "\n}\n"
    out = s.replace("\n", nl) if nl == "\r\n" else s
    return out.encode("utf-8")

def emit_v4_fixture():
    strat = json.loads(HOP_JSON.read_text(encoding="utf-8"))["strategies"]
    assert len(strat) == 264
    import openpyxl
    wb = openpyxl.load_workbook(XLSX, read_only=True, data_only=True)
    ws = wb["CLASIFICACION_264"]
    surf = {}
    for row in ws.iter_rows(values_only=True):
        if row and row[0] and str(row[0]).startswith("MEV-"):
            surf[str(row[0])] = str(row[4])
    wb.close()
    assert len(surf) == 264, "CLASIFICACION_264 rows != 264"
    rows = []
    for s in strat:
        hops = sorted(int(x) for x in s["mask"].split("/"))
        rows.append({"m": s["mev_id"],
                     "mask": sum(1 << (h - 2) for h in hops),
                     "h": hops,
                     "s": surf[s["mev_id"]]})
    doc = {
        "_source": ("01_SSOT/strategy_hop_map.json (integrado-supremo, SSOT v4; "
                    "frozen copy at docs/integration-v4/releases/" + R.name + "/SSOT/); "
                    "surface column s from workbook ArbitrageX_v4_264_60hojas.xlsx "
                    "sheet CLASIFICACION_264"),
        "_generator": "docs/integration-v4/releases/" + R.name + "/gen/gen_ssot_v4_rs.py (t9 alpha2)",
        "rows": rows,
    }
    return json.dumps(doc, ensure_ascii=False, separators=(",", ":")).encode("utf-8")

def verify_bridge():
    src = (WS / "backend/searcher-rs/src/route_discovery/hop_cycle_bridge.rs").read_text(encoding="utf-8")
    mn = re.search(r"pub const MIN_BRIDGE_HOPS: usize = (\d+);", src)
    mx = re.search(r"pub const MAX_BRIDGE_HOPS: usize = (\d+);", src)
    assert mn and mx, "bridge constants not found"
    assert int(mn.group(1)) == 3 and int(mx.group(1)) == 7, "bridge hop bounds drifted"
    strat = json.loads(HOP_JSON.read_text(encoding="utf-8"))["strategies"]
    all_hops = sorted({int(x) for s in strat for x in s["mask"].split("/")})
    line = ("hop_cycle_bridge verify (t9 alpha2, stub v4 'ciclos 3-7 hops')\n"
            "MIN_BRIDGE_HOPS == " + mn.group(1) + " (expect 3): OK\n"
            "MAX_BRIDGE_HOPS == " + mx.group(1) + " (expect 7): OK\n"
            "SSOT v4 hop universe: " + str(all_hops) +
            " (bridge owns 3..=7; hop 2 stays dex_engine-exclusive)\n"
            "stub 04_DIFFS/hop_cycle_bridge.rs.diff ('+ // ciclos 3-7 hops') SATISFIED by "
            "existing code (constants MIN/MAX_BRIDGE_HOPS). No patch needed.\n")
    return line.encode("utf-8")

if __name__ == "__main__":
    OUT.mkdir(parents=True, exist_ok=True)
    det = rebuild_detector_policy_rs()
    (OUT / "detector_policy.rs").write_bytes(det)
    print("detector_policy.rs:", len(det), "bytes")
    fx = emit_v4_fixture()
    (OUT / "strategy_hop_map.v4.fixture.json").write_bytes(fx)
    print("strategy_hop_map.v4.fixture.json:", len(fx), "bytes")
    (OUT / "hop_cycle_bridge.verify.txt").write_bytes(verify_bridge())
    print("hop_cycle_bridge.verify.txt written")
    print("OK")
